import hashlib, marshal, sys, os, hmac as _hm

import time as _tm

def _ad():
    try:
        with open("/proc/self/status", "r") as f:
            for l in f:
                if l.startswith("TracerPid"):
                    if int(l.split()[1]) != 0: os._exit(9)
                    break
    except: pass
    _t0 = _tm.perf_counter()
    for _i in range(100000): pass
    if (_tm.perf_counter() - _t0) > 0.05: os._exit(9)
    if sys.gettrace() is not None or sys.getprofile() is not None: os._exit(9)
    try:
        with open("/proc/self/stat", "r") as f:
            _ppid = int(f.read().split()[3])
        with open("/proc/" + str(_ppid) + "/comm", "r") as f:
            _pn = f.read().strip()
        if _pn in ("gdb","strace","ltrace","pdb","py-spy"): os._exit(9)
    except: pass

_ad()

_s = bytes.fromhex("18f0f9fd08d02f6f6860def25d9ee491")
_n = bytes.fromhex("816aa7827a6989f94d84de15b9eb2ccb")
_h = bytes.fromhex("86493220806019a2664c9c3f5ae45f4bf674dc2394f726babcb575976d723f70")
_d = bytes.fromhex("")

_m0 = bytes.fromhex("948349c50c9f6b47")
_p0 = bytes.fromhex("646e50853b54e60c")
_m1 = bytes.fromhex("45ec2cd585c7101c")
_p1 = bytes.fromhex("63036e9a4d1adad4")
_m2 = bytes.fromhex("bb04aaacc18b22c6")
_p2 = bytes.fromhex("138f351057450680")
_m3 = bytes.fromhex("e65f5d85e69ebb0d")
_p3 = bytes.fromhex("21b9d62eb8039fbf")

_k = bytes(a^b for a,b in zip(_p0,_m0)) + bytes(a^b for a,b in zip(_p1,_m1)) + bytes(a^b for a,b in zip(_p2,_m2)) + bytes(a^b for a,b in zip(_p3,_m3))

_dk = hashlib.pbkdf2_hmac("sha256", _k, _s, 5000, dklen=32)

_hk = hashlib.sha256(_dk).digest()
_hv = _hm.new(_hk, _d, hashlib.sha256).digest()
if _hv != _h: os._exit(7)

def _dec(data, dk, nonce):
    r = bytearray(); c = 0; o = 0
    while o < len(data):
        ks = hashlib.sha256(dk + nonce + c.to_bytes(8, "big")).digest()
        ch = data[o:o+32]
        for i in range(len(ch)): r.append(ch[i] ^ ks[i])
        o += 32; c += 1
    return bytes(r)

import builtins as _bi
_ex = bytes([101,120,101,99]).decode()
_co = bytes([99,111,109,112,105,108,101]).decode()
_re = getattr(_bi, _ex, None)
_rc = getattr(_bi, _co, None)
if _re is None or _rc is None: os._exit(11)
if hasattr(_re, "__module__") and _re.__module__ != "builtins": os._exit(12)
if hasattr(_rc, "__module__") and _rc.__module__ != "builtins": os._exit(13)
if sys.gettrace() is not None or sys.getprofile() is not None: os._exit(14)

_m = _dec(_d, _dk, _n)
exec(marshal.loads(_m))
try:
    del _m; del _d; del _dk; del _k
    del _s; del _n; del _h; del _p0; del _p1; del _p2; del _p3
    del _m0; del _m1; del _m2; del _m3
except: pass